export function dashboardHtml(): string {
  return `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>烛龙·玄枢 · NSS 控制台</title>
  <style>
    :root{color-scheme:dark;--bg:#0b0d0e;--surface:#121619;--surface2:#181e22;--line:#2b3338;--line2:#3a454b;--text:#edf1f2;--muted:#98a4aa;--green:#45c58a;--blue:#63aee8;--amber:#e4b85b;--red:#ec7272;--violet:#b29aeb;--orange:#e59a66;font-family:Inter,"PingFang SC","Microsoft YaHei",system-ui,sans-serif}
    *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);letter-spacing:0}button,input,select,textarea{font:inherit;letter-spacing:0}button{cursor:pointer}.shell{min-height:100vh}.topbar{height:60px;display:flex;align-items:center;padding:0 20px;border-bottom:1px solid var(--line);background:#0e1113;position:sticky;top:0;z-index:5}.brand{font-size:15px;font-weight:700;white-space:nowrap}.brand b{color:var(--green)}.tabs{display:flex;gap:3px;margin-left:auto}.tab,.ghost,.primary,.danger{min-height:36px;border:1px solid transparent;border-radius:6px;padding:7px 11px;color:var(--muted);background:transparent}.tab[aria-selected=true],.ghost:hover{background:var(--surface2);color:var(--text);border-color:var(--line)}.primary{background:var(--green);color:#07150f;font-weight:700}.primary:hover{background:#5bd39b}.danger{border-color:#684040;color:#f09292}.danger:hover{background:#261718}.primary:disabled,.danger:disabled{opacity:.42;cursor:not-allowed}.screen[hidden]{display:none!important}.page{max-width:1440px;margin:0 auto;padding:24px}.page-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding-bottom:20px;border-bottom:1px solid var(--line)}.eyebrow{text-transform:uppercase;color:var(--muted);font-size:11px;font-weight:650}.page-head h1,.headline h1{margin:5px 0 0;font-size:22px;line-height:1.3}.status-row{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.status{display:inline-flex;align-items:center;gap:6px;min-height:28px;padding:4px 8px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:12px}.status:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--muted)}.status.ok{color:#bdebd4}.status.ok:before{background:var(--green)}.status.warn{color:#efd292}.status.warn:before{background:var(--amber)}.status.bad{color:#f3a2a2}.status.bad:before{background:var(--red)}.controls{display:grid;grid-template-columns:minmax(150px,190px) minmax(130px,170px) minmax(150px,190px) 1fr auto;align-items:end;gap:14px;padding:18px 0;border-bottom:1px solid var(--line)}.field{display:grid;gap:7px}.field label{font-size:12px;color:var(--muted)}.field input,.field select,.review select,.review textarea,.token input{width:100%;height:38px;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:8px 10px}.field input:disabled{opacity:.48;cursor:not-allowed}.switch-field{display:flex;align-items:center;gap:9px;height:38px;color:var(--text);font-size:13px}.switch-field input{width:17px;height:17px;accent-color:var(--green)}.control-actions{display:flex;gap:8px}.error-band{margin-top:14px;border-left:3px solid var(--red);background:#1c1314;color:#f1b0b0;padding:10px 12px;font-size:13px}.error-band[hidden]{display:none}.metrics{display:grid;grid-template-columns:repeat(6,minmax(100px,1fr));border-bottom:1px solid var(--line)}.metric{padding:17px 14px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.metric strong{display:block;font-size:21px}.metric span{display:block;color:var(--muted);font-size:11px;margin-top:5px}.arena-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(340px,.85fr);gap:28px;padding-top:24px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.section-head h2{font-size:15px;margin:0}.section-head select{max-width:260px;background:var(--surface);border:1px solid var(--line);color:var(--text);border-radius:6px;padding:7px 9px}.job-state{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--muted)}.dot.completed{background:var(--green)}.dot.running,.dot.queued,.dot.stopping{background:var(--blue)}.dot.failed,.dot.aborted{background:var(--red)}.activity{position:relative;border-top:1px solid var(--line);max-height:620px;overflow:auto}.activity:before{content:"";position:absolute;left:19px;top:22px;bottom:22px;width:1px;background:var(--line)}.activity-row{display:grid;grid-template-columns:76px 120px minmax(0,1fr);gap:12px;padding:10px 2px;border-bottom:1px solid var(--line);font-size:12px}.activity-row time,.activity-row .type{color:var(--muted)}.activity-row .detail{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.feed-item{position:relative;display:grid;grid-template-columns:40px minmax(0,1fr);gap:11px;padding:12px 4px;border-bottom:1px solid var(--line);background:var(--bg)}.feed-node{width:28px;height:28px;margin-left:2px;border:1px solid var(--line2);border-radius:50%;background:var(--surface2);display:grid;place-items:center;color:var(--muted);font-size:11px;z-index:1}.feed-body{min-width:0}.feed-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px}.feed-title{font-size:13px;font-weight:650;word-break:break-word}.feed-meta{flex:none;color:var(--muted);font:11px/1.4 ui-monospace,SFMono-Regular,Menlo,monospace}.feed-summary{margin-top:5px;color:#cbd4d7;font-size:13px;line-height:1.55;white-space:pre-wrap;word-break:break-word}.feed-type{margin-top:5px;color:#727f85;font:11px/1.4 ui-monospace,SFMono-Regular,Menlo,monospace}.feed-turn{background:var(--surface2);padding-top:14px;padding-bottom:14px}.feed-turn .feed-node{box-shadow:0 0 0 5px #22292e}.feed-turn .feed-title{font-size:15px}.feed-turn .feed-summary{display:none}.feed-kind-decision .feed-node{color:var(--violet)}.feed-kind-action .feed-node{color:var(--blue)}.feed-kind-observation .feed-node{color:var(--green)}.feed-kind-checkpoint .feed-node{color:var(--amber)}.feed-kind-revision .feed-node{color:var(--orange)}.feed-kind-finding .feed-node{color:var(--red)}.empty{padding:56px 16px;text-align:center;color:var(--muted);font-size:13px}.attempts,.wrong-questions{display:grid;gap:8px}.attempt{display:grid;grid-template-columns:46px minmax(0,1fr) auto;align-items:center;gap:10px;border:1px solid var(--line);border-radius:6px;background:var(--surface);padding:11px 12px}.attempt-id{font-weight:700;color:var(--muted)}.attempt-main{min-width:0}.attempt-title{font-size:13px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.attempt-meta{font-size:11px;color:var(--muted);margin-top:4px}.outcome{font-size:11px;border:1px solid var(--line2);border-radius:999px;padding:4px 7px;color:var(--muted)}.outcome.solved{color:#bdebd4;border-color:#35674e}.outcome.wrong,.outcome.abandoned,.outcome.infrastructure-error{color:#f1a0a0;border-color:#704444}.wrong-bank{margin-top:24px;padding-top:18px;border-top:1px solid var(--line)}.wrong-bank .section-head{margin-bottom:10px}.wrong-bank-count{color:var(--muted);font-size:11px}.summary{margin-top:24px;border-top:1px solid var(--line);padding-top:18px}.summary-block{margin-top:15px}.summary-block h3{font-size:12px;color:var(--muted);margin:0 0 8px;text-transform:uppercase}.summary-block ul{margin:0;padding-left:18px;color:#d3dbde;font-size:13px;line-height:1.6}.summary-block.gaps li::marker{color:var(--amber)}.summary-block.next li::marker{color:var(--blue)}.runs-layout{display:grid;grid-template-columns:280px minmax(420px,1fr) 340px;min-height:calc(100vh - 60px)}.sidebar,.inspector{padding:18px;border-right:1px solid var(--line);overflow:auto}.inspector{border-right:0;border-left:1px solid var(--line)}.main{padding:20px 26px 50px;overflow:auto}.run-list{display:grid;gap:6px;margin-top:12px}.run{width:100%;text-align:left;padding:11px;border:1px solid transparent;border-radius:6px;background:transparent;color:var(--text)}.run:hover,.run.active{background:var(--surface);border-color:var(--line)}.run-title{font-size:13px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.run-meta,.muted{color:var(--muted);font-size:12px;margin-top:6px}.headline{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.integrity{padding:6px 9px;border:1px solid var(--line);border-radius:999px;color:var(--green);font-size:12px;white-space:nowrap}.stats{display:flex;gap:18px;flex-wrap:wrap;margin:17px 0 24px;color:var(--muted);font-size:12px}.stats strong{color:var(--text);font-size:17px;margin-right:5px}.timeline{position:relative;margin-left:8px}.timeline:before{content:"";position:absolute;left:13px;top:8px;bottom:8px;width:1px;background:var(--line)}.event{position:relative;display:grid;grid-template-columns:28px 1fr;gap:13px;margin:0 0 12px;border:0;background:transparent;color:inherit;width:100%;text-align:left}.node{width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:var(--surface2);border:1px solid var(--line);z-index:1;font-size:11px;color:var(--muted)}.event.active .node{outline:2px solid var(--green);outline-offset:2px}.event-card{padding:12px 14px;background:var(--surface);border:1px solid var(--line);border-radius:6px}.event-card:hover{border-color:var(--line2)}.event-head{display:flex;gap:10px;justify-content:space-between}.event-title{font-size:13px;font-weight:650}.event-time{font-size:11px;color:var(--muted)}.event-summary{display:block;margin-top:6px;color:#cbd4d7;font-size:13px;line-height:1.5}.kind-turn .node,.kind-plan .node,.kind-hypothesis .node,.kind-lesson .node{color:var(--violet)}.kind-decision .node{color:var(--violet)}.kind-action .node{color:var(--blue)}.kind-observation .node{color:var(--green)}.kind-checkpoint .node{color:var(--amber)}.kind-revision .node{color:var(--orange)}.kind-finding .node{color:var(--red)}.denied{border-color:#704545}.inspector h2{font-size:16px;margin:7px 0 12px}.detail-box{white-space:pre-wrap;word-break:break-word;background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:12px;max-height:420px;overflow:auto;color:#c6d0d3;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.review{display:grid;gap:8px;margin-top:16px}.review textarea{height:auto;min-height:72px;resize:vertical}.review-log{margin-top:16px;display:grid;gap:8px}.review-item{border-left:2px solid var(--amber);padding-left:10px;font-size:12px;color:#cdd5d7}.experience-page{max-width:1200px;margin:0 auto;padding:24px}.experiences{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;margin-top:20px}.lesson{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:15px}.lesson h3{margin:0 0 7px;font-size:15px}.lesson ul{padding-left:18px;color:#ccd5d8;font-size:13px;line-height:1.5}.lesson-actions{display:flex;justify-content:space-between;align-items:center;margin-top:12px}.badge{font-size:11px;border:1px solid var(--line);border-radius:999px;padding:4px 7px;color:var(--green)}.badge.disabled{color:var(--red)}.token{display:none;position:fixed;inset:0;background:#050607e8;align-items:center;justify-content:center;z-index:10}.token.open{display:flex}.token-box{width:min(400px,calc(100% - 32px));background:var(--surface2);border:1px solid var(--line);border-radius:6px;padding:20px}.token-box h2{margin-top:0;font-size:18px}
    @media(max-width:1050px){.metrics{grid-template-columns:repeat(3,1fr)}.metric:nth-child(3){border-right:0}.arena-grid{grid-template-columns:1fr}.runs-layout{grid-template-columns:240px 1fr}.inspector{grid-column:1/-1;border-left:0;border-top:1px solid var(--line)}.detail-box{max-height:260px}}
    @media(max-width:720px){.topbar{height:auto;min-height:58px;padding:10px 12px;display:grid;grid-template-columns:1fr;align-items:start}.brand{padding:4px 0 2px}.tabs{margin-left:0;width:100%;overflow:visible}.tab{white-space:nowrap;padding:7px 8px;flex:1}.page,.experience-page{padding:16px}.page-head{display:block}.status-row{justify-content:flex-start;margin-top:14px}.controls{grid-template-columns:1fr 1fr}.control-actions{grid-column:1/-1}.control-actions button{flex:1}.metrics{grid-template-columns:repeat(2,1fr)}.metric:nth-child(2n){border-right:0}.metric:nth-child(3){border-right:1px solid var(--line)}.arena-grid{gap:22px}.activity-row{grid-template-columns:62px 94px minmax(0,1fr);gap:8px}.runs-layout{display:block}.sidebar{border-right:0;border-bottom:1px solid var(--line);max-height:240px}.main,.inspector{padding:16px}.headline{display:block}.integrity{display:inline-block;margin-top:9px}}
  </style>
<style>
  .manual-form{display:grid;gap:14px;padding:18px 0;border-bottom:1px solid var(--line)}.manual-form label{display:grid;gap:7px;color:var(--muted);font-size:12px}.manual-form textarea{width:100%;min-height:240px;resize:vertical;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:10px;line-height:1.55}.manual-attachments{display:grid;gap:8px}.manual-attachments input{width:100%;min-height:40px;color:var(--muted);background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:7px}.manual-attachments input::file-selector-button{height:26px;margin-right:10px;border:1px solid var(--line2);border-radius:5px;color:var(--text);background:var(--surface2);cursor:pointer}.manual-file-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.manual-file-clear{width:28px;height:28px;padding:0;border:1px solid var(--line);border-radius:5px;color:var(--muted);background:transparent}.manual-file-list{display:flex;gap:6px;flex-wrap:wrap}.manual-file{max-width:100%;padding:5px 7px;border:1px solid var(--line);border-radius:5px;color:#cdd5d7;background:var(--surface);font-size:11px;overflow-wrap:anywhere}.manual-controls{display:flex;align-items:end;gap:14px;flex-wrap:wrap}.manual-controls .field{width:150px}.manual-controls .control-actions{margin-left:auto}.manual-job-list{display:grid;gap:18px;margin-top:24px}.manual-job{border-top:1px solid var(--line);padding-top:16px}.manual-job-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.manual-job-title{font-size:15px;font-weight:650}.manual-job-meta{margin-top:6px;color:var(--muted);font-size:12px}.manual-task-list{display:grid;gap:6px;margin-top:12px}.manual-task{display:grid;grid-template-columns:30px minmax(0,1fr) auto;align-items:center;gap:10px;padding:9px 10px;background:var(--surface);border:1px solid var(--line);border-radius:6px}.manual-task-index{color:var(--muted);font:11px ui-monospace,SFMono-Regular,Menlo,monospace}.manual-task-text{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.manual-task-status{font-size:11px;color:var(--muted)}.manual-task-status.completed{color:#bdebd4}.manual-task-status.failed,.manual-task-status.aborted{color:#f1a0a0}.manual-task-run{border:0;background:transparent;color:var(--blue);font-size:11px;padding:0}.manual-task-run:hover{text-decoration:underline}@media(max-width:720px){.manual-controls{display:grid;grid-template-columns:1fr}.manual-controls .field{width:100%}.manual-controls .control-actions{margin-left:0}.manual-controls .control-actions button{flex:1;white-space:nowrap}}
  .manual-controls .switch-field{display:flex;align-items:center;gap:8px;height:38px;color:var(--text);font-size:13px}.manual-controls .switch-field input{width:17px;height:17px;accent-color:var(--green)}.manual-task-actions{display:flex;align-items:center;justify-content:flex-end;gap:9px}.manual-task-result{grid-column:2/-1;min-width:0;border-top:1px solid var(--line);padding-top:9px}.manual-flag-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:9px}.manual-result-label{color:var(--green);font-size:11px;font-weight:700}.manual-flag{min-width:0;color:#eaf7f0;font:13px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.manual-copy{width:56px;min-height:30px;padding:4px 7px;font-size:11px}.manual-writeup{margin-top:9px;border-top:1px solid var(--line);padding-top:8px}.manual-writeup summary{color:var(--blue);font-size:12px;cursor:pointer}.manual-writeup-toolbar{display:flex;justify-content:flex-end;margin:7px 0}.manual-writeup pre{max-height:460px;margin:0;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;color:#d5dddf;font:12px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace}.manual-task-error{color:#f1a0a0;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.manual-task-status.skipped{color:#efd292}.question-bank{margin-top:24px;padding-top:18px;border-top:1px solid var(--line)}.question-bank-list{display:grid;gap:6px;margin:12px 0}.question-bank-item{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 10px;background:var(--surface);border:1px solid var(--line);border-radius:6px;font-size:12px}.question-bank-item.solved{border-color:#35674e}.question-bank-detail{color:var(--muted);font-size:11px}.question-bank-status{font-size:11px;color:var(--amber);white-space:nowrap}.question-bank-status.solved{color:var(--green)}.question-bank-meta{color:var(--muted);font-size:12px}@media(max-width:720px){.manual-task{grid-template-columns:24px minmax(0,1fr);align-items:start}.manual-task-actions{grid-column:2;justify-content:flex-start;flex-wrap:wrap}.manual-task-result{grid-column:1/-1}.manual-flag-row{grid-template-columns:1fr auto}.manual-result-label{grid-column:1/-1}.question-bank-item{align-items:flex-start;flex-direction:column;gap:4px}}
</style>
</head>
<body>
<div class="shell">
  <header class="topbar"><div class="brand"><b>烛龙·玄枢</b> · NSS 控制台</div><nav class="tabs"><button class="tab" id="arena-tab" aria-selected="true">Arena</button><button class="tab" id="manual-tab" aria-selected="false">手工解题</button><button class="tab" id="runs-tab" aria-selected="false">运行轨迹</button><button class="tab" id="experience-tab" aria-selected="false">经验库</button></nav></header>
  <main id="arena-screen" class="screen page">
    <div class="page-head"><div><div class="eyebrow">NSSCTF Agent Arena</div><h1>自动解题作业</h1></div><div class="status-row" id="readiness"></div></div>
    <form id="arena-form" class="controls"><div class="field"><label>运行模式</label><label class="switch-field"><input id="continuous" type="checkbox" checked> 持续运行</label></div><div class="field"><label for="max-attempts">目标题数</label><input id="max-attempts" type="number" min="1" max="50" value="1" disabled></div><div class="field"><label>提交策略</label><label class="switch-field"><input id="auto-submit" type="checkbox" checked> 自动提交</label></div><div></div><div class="control-actions"><button id="start-arena" class="primary" type="submit">▶ 开始解题</button><button id="stop-arena" class="danger" type="button" disabled title="停止当前作业">■ 停止</button></div></form>
    <div id="arena-error" class="error-band" hidden></div>
    <div class="metrics" id="arena-metrics"></div>
    <div class="arena-grid"><section><div class="section-head"><h2>实时执行轨迹</h2><select id="job-select" aria-label="Arena 作业历史"></select></div><div class="job-state" id="job-state"></div><div class="activity" id="activity"></div></section><section><div class="section-head"><h2>题目结果</h2></div><div class="attempts" id="attempts"></div><div class="wrong-bank"><div class="section-head"><h2>错题库</h2><span id="wrong-bank-count" class="wrong-bank-count"></span></div><div class="wrong-questions" id="wrong-questions"></div></div><div class="summary" id="capability-summary"></div></section></div>
  </main>
  <main id="manual-screen" class="screen page" hidden>
    <div class="page-head"><div><div class="eyebrow">Manual runs</div><h1>手工解题</h1></div></div>
    <form id="manual-form" class="manual-form">
      <label for="manual-tasks">题目</label>
      <textarea id="manual-tasks" placeholder="粘贴题目内容；多题之间用单独一行 --- 分隔"></textarea>
      <div class="manual-attachments">
        <div class="manual-file-head"><label for="manual-files">附件（应用到本批全部题目）</label><button id="manual-file-clear" class="manual-file-clear" type="button" title="清空附件" hidden>×</button></div>
        <input id="manual-files" type="file" multiple>
        <div id="manual-file-list" class="manual-file-list"></div>
      </div>
      <div class="manual-controls">
        <div class="field"><label for="manual-concurrency">并发数</label><input id="manual-concurrency" type="number" min="1" max="8" value="1"></div>
        <div class="field"><label for="manual-race-agents">每题 agent 数</label><input id="manual-race-agents" type="number" min="1" max="8" value="1"></div>
        <label class="switch-field" for="manual-writeup"><input id="manual-writeup" type="checkbox" checked>生成 WP</label>
        <div class="control-actions"><button id="manual-submit" class="primary" type="submit">▶ 提交解题</button><button id="manual-stop" class="danger" type="button" disabled>■ 停止</button></div>
      </div>
    </form>
    <div id="manual-error" class="error-band" hidden></div>
    <section class="question-bank"><div class="section-head"><div><h2>本地题库</h2><div id="question-bank-meta" class="question-bank-meta"></div></div><button id="question-bank-start" class="primary" type="button" disabled>▶ 处理未完成题库</button></div><div id="question-bank-list" class="question-bank-list"></div></section>
    <section><div class="section-head"><h2>批量作业</h2></div><div id="manual-jobs" class="manual-job-list"></div></section>
  </main>
  <div id="runs-screen" class="screen runs-layout" hidden>
    <aside class="sidebar"><div class="eyebrow">Runs</div><div id="run-list" class="run-list"></div></aside>
    <main class="main"><div id="trace-empty" class="empty">选择一次运行</div><div id="trace" hidden><div class="headline"><div><div class="eyebrow" id="trace-category"></div><h1 id="trace-title"></h1><div class="muted" id="trace-id"></div></div><div class="integrity" id="integrity"></div></div><div class="stats" id="stats"></div><div class="timeline" id="timeline"></div></div></main>
    <aside class="inspector"><div class="eyebrow">Inspector</div><h2 id="detail-title">尚未选择步骤</h2><pre id="detail" class="detail-box">选择时间线记录</pre><form id="review-form" class="review" hidden><select id="review-verdict" aria-label="复核结论"><option value="correct">判断正确</option><option value="incorrect">存在错误</option><option value="uncertain">需要确认</option></select><textarea id="review-note" placeholder="复核依据" required></textarea><textarea id="review-correction" placeholder="建议修正（可选）"></textarea><button class="primary" type="submit">保存复核</button></form><div id="review-log" class="review-log"></div></aside>
  </div>
  <main id="experience-screen" class="screen experience-page" hidden><div class="page-head"><div><div class="eyebrow">Validated experience</div><h1>平台验真经验</h1></div></div><div id="experience-list" class="experiences"></div></main>
</div>
<div id="token-modal" class="token"><form id="token-form" class="token-box"><h2>服务令牌</h2><input id="token-input" type="password" autocomplete="current-password" placeholder="XUANSHU_SERVER_TOKEN" required><div style="margin-top:12px;text-align:right"><button class="primary" type="submit">继续</button></div></form></div>
<script>
(() => {
  const state={token:sessionStorage.getItem('xuanshu-token')||'',runs:[],trace:null,selected:null,arenaStatus:null,job:null,jobId:null,arenaTrace:null,arenaRunId:null,manualJobs:[],manualJobId:null,questionBank:null,tab:'arena'};
  const $=id=>document.getElementById(id);
  const terminal=new Set(['completed','failed','aborted']);
  function jobDisplayStatus(job){const accuracy=job.accuracyPercent??job.summary?.accuracyPercent;return job.status==='completed'?(accuracy===100?'solved':'settled'):job.status}
  async function api(path,init={}){const headers={...(init.headers||{})};if(state.token)headers.authorization='Bearer '+state.token;if(init.body)headers['content-type']='application/json';const res=await fetch(path,{...init,headers});if(res.status===401){$('token-modal').classList.add('open');throw new Error('unauthorized')}const body=await res.json();if(!res.ok)throw new Error(body.error||('HTTP '+res.status));return body}
  function fmtTime(v){if(!v)return '—';try{return new Date(v).toLocaleString('zh-CN',{hour12:false})}catch{return v}}
  function shortTime(v){if(!v)return '—';try{return new Date(v).toLocaleTimeString('zh-CN',{hour12:false})}catch{return v}}
  function addStatus(box,label,ok,warn){const item=document.createElement('span');item.className='status '+(ok?'ok':warn?'warn':'bad');item.textContent=label;box.appendChild(item)}
  function setArenaError(message){$('arena-error').hidden=!message;$('arena-error').textContent=message||''}
  function setManualError(message){$('manual-error').hidden=!message;$('manual-error').textContent=message||''}
  function renderReadiness(){const r=state.arenaStatus?.readiness;if(!r)return;const box=$('readiness');box.textContent='';addStatus(box,'Arena 凭据',r.arenaCredentialConfigured);addStatus(box,'模型凭据',r.modelCredentialConfigured&&r.modelHeadersConfigured);addStatus(box,'受控范围',r.scopeControlled);if(r.allowedCategories?.length)addStatus(box,'题型: '+r.allowedCategories.join('/'),true);addStatus(box,r.sandbox.reachable?'沙箱在线':'沙箱待启动',r.sandbox.reachable,!r.sandbox.reachable);$('start-arena').disabled=!r.ready||Boolean(state.job&&!terminal.has(state.job.status));if(r.issues.length)setArenaError(r.issues.join(' · '));else if(!state.job?.error)setArenaError('')}
  function metric(value,label){const div=document.createElement('div');div.className='metric';const strong=document.createElement('strong');strong.textContent=String(value);const span=document.createElement('span');span.textContent=label;div.append(strong,span);return div}
  function renderMetrics(){const box=$('arena-metrics');box.textContent='';const s=state.job?.summary;const attempts=state.job?.attempts||[];const target=state.job?(state.job.options.continuous?'持续':state.job.options.maxAttempts):0;box.append(metric(state.job?.completedAttempts||0,'已结算'),metric(target,'目标'),metric(s?.solved||attempts.filter(a=>a.outcome==='solved').length,'正确'),metric(state.arenaStatus?.wrongQuestions?.length||0,'错题'),metric(s?.accuracyPercent==null?'—':s.accuracyPercent+'%','正确率'),metric(s?.promotedLessons||attempts.reduce((n,a)=>n+(a.run.promotedLessons||0),0),'晋升经验'))}
  function renderJobSelect(){const select=$('job-select');select.textContent='';const jobs=state.arenaStatus?.jobs||[];if(!jobs.length){const option=document.createElement('option');option.textContent='暂无作业';option.value='';select.appendChild(option);select.disabled=true;return}select.disabled=false;for(const job of jobs){const option=document.createElement('option');option.value=job.id;const target=job.continuous||job.targetAttempts==null?'∞':job.targetAttempts;option.textContent=fmtTime(job.createdAt)+' · '+jobDisplayStatus(job)+' · '+job.completedAttempts+'/'+target;option.selected=job.id===(state.jobId||jobs[0].id);select.appendChild(option)}}
  function currentArenaRunId(){const attempts=state.job?.attempts||[];const events=state.job?.activity||[];return state.job?.currentRunId||attempts.at(-1)?.run?.id||events.at(-1)?.runId||null}
  function renderActivity(){const box=$('activity');box.textContent='';const timeline=state.arenaTrace?.timeline||[];if(timeline.length){let round=0;const grouped=timeline.map(event=>{if(event.kind==='turn'&&Number.isInteger(event.data?.turn))round=event.data.turn;return{event,round}});for(const item of grouped.reverse()){const event=item.event;const row=document.createElement('div');row.className='feed-item feed-kind-'+event.kind+(event.kind==='turn'?' feed-turn':'');const node=document.createElement('span');node.className='feed-node';node.textContent=icons[event.kind]||'·';const body=document.createElement('div');body.className='feed-body';const head=document.createElement('div');head.className='feed-head';const title=document.createElement('span');title.className='feed-title';title.textContent=event.title;const meta=document.createElement('span');meta.className='feed-meta';meta.textContent='R'+(item.round||'—')+'  '+shortTime(event.timestamp);head.append(title,meta);const summary=document.createElement('div');summary.className='feed-summary';summary.textContent=event.summary;const type=document.createElement('div');type.className='feed-type';type.textContent=event.kind==='decision'?'public_decision_note':event.kind==='turn'?'llm_round_start':event.kind;body.append(head,summary,type);row.append(node,body);box.appendChild(row)}return}const events=state.job?.activity||[];if(!events.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=state.job?'等待运行事件':'尚未启动作业';box.appendChild(empty);return}for(const event of [...events].reverse()){const row=document.createElement('div');row.className='activity-row';const time=document.createElement('time');time.textContent=shortTime(event.timestamp);const type=document.createElement('span');type.className='type';type.textContent=event.type;const detail=document.createElement('span');detail.className='detail';detail.textContent=event.detail;row.append(time,type,detail);box.appendChild(row)}}
  function renderAttempts(){const box=$('attempts');box.textContent='';const attempts=state.job?.attempts||[];if(!attempts.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='暂无题目结果';box.appendChild(empty);return}for(const attempt of attempts){const item=document.createElement('article');item.className='attempt';const id=document.createElement('span');id.className='attempt-id';id.textContent='#'+attempt.attemptId;const main=document.createElement('div');main.className='attempt-main';const title=document.createElement('div');title.className='attempt-title';title.textContent=attempt.category;const meta=document.createElement('div');meta.className='attempt-meta';meta.textContent=attempt.run.turns+' 回合 · '+attempt.run.toolCalls+' 工具 · '+attempt.submissionAttempts+' 次提交';main.append(title,meta);const outcome=document.createElement('span');outcome.className='outcome '+attempt.outcome;outcome.textContent=attempt.outcome;item.append(id,main,outcome);box.appendChild(item)}}
  function renderWrongQuestions(){const box=$('wrong-questions');box.textContent='';const questions=state.arenaStatus?.wrongQuestions||[];$('wrong-bank-count').textContent=questions.length+' 题';if(!questions.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='暂无错题';box.appendChild(empty);return}for(const question of questions){const item=document.createElement('article');item.className='attempt';const id=document.createElement('span');id.className='attempt-id';id.textContent='#'+question.attemptId;const main=document.createElement('div');main.className='attempt-main';const title=document.createElement('div');title.className='attempt-title';title.textContent=question.category;const meta=document.createElement('div');meta.className='attempt-meta';meta.textContent=question.attachmentCount+' 个附件 · '+question.failureCount+' 次记录 · '+fmtTime(question.lastFailedAt);main.append(title,meta);const outcome=document.createElement('span');outcome.className='outcome '+question.lastOutcome;outcome.textContent=question.lastOutcome;item.append(id,main,outcome);box.appendChild(item)}}
  function summaryBlock(title,items,className){if(!items?.length)return null;const block=document.createElement('div');block.className='summary-block '+(className||'');const h=document.createElement('h3');h.textContent=title;const list=document.createElement('ul');for(const text of items){const li=document.createElement('li');li.textContent=text;list.appendChild(li)}block.append(h,list);return block}
  function renderSummary(){const box=$('capability-summary');box.textContent='';const s=state.job?.summary;if(!s){const empty=document.createElement('div');empty.className='empty';empty.textContent='作业完成后生成能力总结';box.appendChild(empty);return}const blocks=[summaryBlock('已验证',s.strengths),summaryBlock('能力缺口',s.gaps,'gaps'),summaryBlock('下一步',s.nextActions,'next')].filter(Boolean);for(const block of blocks)box.appendChild(block)}
  function renderArena(){renderReadiness();renderJobSelect();renderMetrics();renderActivity();renderAttempts();renderWrongQuestions();renderSummary();const active=Boolean(state.job&&!terminal.has(state.job.status));$('stop-arena').disabled=!state.job||!['queued','running'].includes(state.job.status);$('start-arena').disabled=active||!state.arenaStatus?.readiness.ready;const jobState=$('job-state');jobState.textContent='';if(state.job){const displayStatus=jobDisplayStatus(state.job);const dot=document.createElement('span');dot.className='dot '+(displayStatus==='settled'?'completed':displayStatus);if(displayStatus==='settled')dot.style.background='var(--amber)';const text=document.createElement('span');text.textContent=displayStatus+' · '+fmtTime(state.job.startedAt||state.job.createdAt)+(state.job.currentRunId?' · run '+state.job.currentRunId:'');jobState.append(dot,text);if(state.job.error)setArenaError(state.job.error)}}
  async function refreshArenaTrace(){const id=currentArenaRunId();if(!id){state.arenaTrace=null;state.arenaRunId=null;return}try{const trace=await api('/v1/runs/'+id+'/trace');if(id===currentArenaRunId()){state.arenaTrace=trace;state.arenaRunId=id}}catch{if(id===currentArenaRunId()&&state.arenaRunId!==id)state.arenaTrace=null}}
  async function loadArenaStatus(){state.arenaStatus=await api('/v1/arena/status');const jobs=state.arenaStatus.jobs||[];if(!state.jobId&&jobs[0])state.jobId=jobs[0].id;if(state.jobId){const found=jobs.some(job=>job.id===state.jobId);if(found)state.job=(await api('/v1/arena/jobs/'+state.jobId)).job;else{state.jobId=null;state.job=null}}await refreshArenaTrace();renderArena()}
  async function pollJob(){if(!state.jobId)return;try{state.job=(await api('/v1/arena/jobs/'+state.jobId)).job;await refreshArenaTrace();renderArena();if(terminal.has(state.job.status)){await loadArenaStatus();await loadRuns()}}catch(error){setArenaError(error.message)}}
  function syncContinuousControl(){const continuous=$('continuous').checked;$('max-attempts').disabled=continuous;$('max-attempts').required=!continuous}
  $('continuous').onchange=syncContinuousControl;syncContinuousControl();
  $('arena-form').onsubmit=async event=>{event.preventDefault();setArenaError('');try{const body={continuous:$('continuous').checked,maxAttempts:Number($('max-attempts').value),autoSubmit:$('auto-submit').checked,idleSeconds:1};const result=await api('/v1/arena/jobs',{method:'POST',body:JSON.stringify(body)});state.job=result.job;state.jobId=result.job.id;state.arenaTrace=null;state.arenaRunId=null;await loadArenaStatus()}catch(error){setArenaError(error.message)}};
  $('stop-arena').onclick=async()=>{if(!state.jobId)return;try{state.job=(await api('/v1/arena/jobs/'+state.jobId+'/stop',{method:'POST',body:'{}'})).job;renderArena()}catch(error){setArenaError(error.message)}};
  $('job-select').onchange=async event=>{state.jobId=event.target.value||null;state.arenaTrace=null;state.arenaRunId=null;if(state.jobId)state.job=(await api('/v1/arena/jobs/'+state.jobId)).job;else state.job=null;await refreshArenaTrace();renderArena()};
  function manualStatusLabel(status){return {queued:'排队中',running:'运行中',stopping:'停止中',completed:'已完成',blocked:'受阻',skipped:'已跳过',failed:'失败',aborted:'已停止'}[status]||status}
  function parseManualTasks(value){const newline=String.fromCharCode(10);return value.replaceAll(String.fromCharCode(13),'').split(newline+'---'+newline).map(item=>item.trim()).filter(Boolean)}
  function fmtBytes(value){if(value<1024)return value+' B';if(value<1024*1024)return (value/1024).toFixed(1)+' KiB';return (value/1024/1024).toFixed(1)+' MiB'}
  function renderManualFiles(){const files=[...$('manual-files').files];const box=$('manual-file-list');box.textContent='';$('manual-file-clear').hidden=!files.length;for(const file of files){const item=document.createElement('span');item.className='manual-file';item.textContent=file.name+' · '+fmtBytes(file.size);box.appendChild(item)}}
  $('manual-files').onchange=renderManualFiles;$('manual-file-clear').onclick=()=>{$('manual-files').value='';renderManualFiles()};
  async function uploadManualFiles(files){let upload=null;for(const file of files){const headers={'x-file-name':encodeURIComponent(file.name)};if(state.token)headers.authorization='Bearer '+state.token;if(upload)headers['x-upload-id']=upload.id;const response=await fetch('/v1/manual/uploads',{method:'POST',headers,body:file});if(response.status===401){$('token-modal').classList.add('open');throw new Error('unauthorized')}const body=await response.json();if(!response.ok)throw new Error(body.error||('HTTP '+response.status));upload=body.upload}return upload}
  async function copyManualText(value,button){let copied=false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);copied=true}}catch{}if(!copied){const area=document.createElement('textarea');area.value=value;area.setAttribute('readonly','');area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();try{copied=document.execCommand('copy')}finally{area.remove()}}if(!copied){setManualError('复制失败，请手动选择内容');return}button.textContent='已复制';setTimeout(()=>{if(button.isConnected)button.textContent='复制'},1200)}
  function manualCopyButton(value,label){const button=document.createElement('button');button.className='ghost manual-copy';button.type='button';button.textContent='复制';button.title='复制 '+label;button.onclick=()=>copyManualText(value,button);return button}
  const manualOpenWriteups=new Set();
  function appendManualTaskResult(row,task){if(!task.flag&&!task.writeup&&!task.error)return;const result=document.createElement('div');result.className='manual-task-result';if(task.flag){const flagRow=document.createElement('div');flagRow.className='manual-flag-row';const label=document.createElement('span');label.className='manual-result-label';label.textContent='FLAG';const flag=document.createElement('code');flag.className='manual-flag';flag.textContent=task.flag;flagRow.append(label,flag,manualCopyButton(task.flag,'FLAG'));result.appendChild(flagRow)}if(task.writeup){const details=document.createElement('details');details.className='manual-writeup';const writeupKey=task.runId||String(task.index);details.open=manualOpenWriteups.has(writeupKey);details.ontoggle=()=>{if(details.open)manualOpenWriteups.add(writeupKey);else manualOpenWriteups.delete(writeupKey)};const summary=document.createElement('summary');summary.textContent='WP';const toolbar=document.createElement('div');toolbar.className='manual-writeup-toolbar';toolbar.appendChild(manualCopyButton(task.writeup,'WP'));const content=document.createElement('pre');content.textContent=task.writeup;details.append(summary,toolbar,content);result.appendChild(details)}if(task.error){const error=document.createElement('div');error.className='manual-task-error';error.textContent=task.error;result.appendChild(error)}row.appendChild(result)}
  function renderQuestionBank(){const bank=state.questionBank;const meta=$('question-bank-meta');const list=$('question-bank-list');const start=$('question-bank-start');meta.textContent='';list.textContent='';if(!bank){meta.textContent='正在读取题库…';start.disabled=true;return}if(bank.error){meta.textContent=bank.error;start.disabled=true;const empty=document.createElement('div');empty.className='empty';empty.textContent='题库尚未配置';list.appendChild(empty);return}const pending=Number.isInteger(bank.pendingCount)?bank.pendingCount:bank.count;const solved=Number.isInteger(bank.solvedCount)?bank.solvedCount:Math.max(0,bank.count-pending);meta.textContent=bank.count+' 题 · '+solved+' 题已通过 · '+pending+' 题待处理 · 阻塞题自动标记跳过';start.textContent=pending?'▶ 处理未完成题库':'✓ 已全部通过';start.disabled=!bank.configured||!pending||Boolean(state.manualJobId&&state.manualJobs.some(job=>job.id===state.manualJobId&&['queued','running','stopping'].includes(job.status)));if(!bank.questions?.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=bank.configured?'题库为空':'题库尚未配置';list.appendChild(empty);return}for(const question of bank.questions){const isSolved=question.status==='solved';const item=document.createElement('div');item.className='question-bank-item'+(isSolved?' solved':'');const title=document.createElement('span');title.textContent=question.title;const detail=document.createElement('span');detail.className='question-bank-detail';detail.textContent=question.category+' · '+question.attachmentCount+' 个公开附件';const status=document.createElement('span');status.className='question-bank-status '+(isSolved?'solved':'pending');status.textContent=isSolved?'已通过':'待处理';item.append(title,detail,status);list.appendChild(item)}}
  function renderManualJobs(){const box=$('manual-jobs');box.textContent='';const jobs=state.manualJobs||[];$('manual-stop').disabled=!state.manualJobId||!jobs.some(job=>job.id===state.manualJobId&&['queued','running','stopping'].includes(job.status));renderQuestionBank();if(!jobs.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='尚未提交手工作业';box.appendChild(empty);return}for(const job of jobs){const section=document.createElement('section');section.className='manual-job';const head=document.createElement('div');head.className='manual-job-head';const title=document.createElement('div');title.className='manual-job-title';title.textContent=manualStatusLabel(job.status)+' · '+fmtTime(job.createdAt);const actions=document.createElement('div');actions.className='control-actions';if(['queued','running','stopping'].includes(job.status)){const stop=document.createElement('button');stop.className='danger';stop.type='button';stop.textContent='■ 停止';stop.onclick=async()=>{try{state.manualJobId=job.id;await api('/v1/manual/jobs/'+job.id+'/stop',{method:'POST',body:'{}'});await loadManualJobs()}catch(error){setManualError(error.message)}};actions.appendChild(stop)}head.append(title,actions);const meta=document.createElement('div');meta.className='manual-job-meta';const attachmentCount=job.tasks[0]?.attachmentCount||0;const processed=(job.completed||0)+(job.skipped||0);meta.textContent=processed+'/'+job.total+' 已处理 · '+(job.skipped||0)+' 跳过 · '+job.running+' 运行中 · '+job.failed+' 失败 · 并发 '+job.concurrency+' · 每题 agent '+(job.raceAgents||1)+(attachmentCount?' · 附件 '+attachmentCount:'')+(job.writeup?' · 生成 WP':'');section.append(head,meta);const list=document.createElement('div');list.className='manual-task-list';for(const task of job.tasks){const row=document.createElement('article');row.className='manual-task';const index=document.createElement('span');index.className='manual-task-index';index.textContent=String(task.index+1).padStart(2,'0');const text=document.createElement('span');text.className='manual-task-text';text.textContent=task.task;const taskActions=document.createElement('div');taskActions.className='manual-task-actions';const status=document.createElement('span');status.className='manual-task-status '+task.status;status.textContent=manualStatusLabel(task.status);taskActions.appendChild(status);if(task.race?.winnerAgent!==undefined){const winner=document.createElement('span');winner.className='manual-task-status completed';winner.textContent='agent '+(task.race.winnerAgent+1)+' 胜出';taskActions.appendChild(winner)}if(task.runId){const run=document.createElement('button');run.className='manual-task-run';run.type='button';run.textContent='查看';run.onclick=()=>{show('runs');loadTrace(task.runId).catch(error=>setManualError(error.message))};taskActions.appendChild(run)}row.append(index,text,taskActions);appendManualTaskResult(row,task);list.appendChild(row)}section.appendChild(list);box.appendChild(section)}}
  async function loadManualJobs(){state.manualJobs=(await api('/v1/manual/jobs')).jobs||[];if(state.manualJobId&&!state.manualJobs.some(job=>job.id===state.manualJobId))state.manualJobId=null;renderManualJobs()}
  async function loadQuestionBank(){state.questionBank=(await api('/v1/question-bank')).questionBank;renderQuestionBank()}
  $('manual-form').onsubmit=async event=>{event.preventDefault();setManualError('');const tasks=parseManualTasks($('manual-tasks').value);const files=[...$('manual-files').files];if(!tasks.length){setManualError('请先粘贴至少一道题目');return}if(tasks.length>20){setManualError('单批最多提交 20 道题目');return}if(files.length>20){setManualError('单批最多上传 20 个附件');return}if(files.some(file=>file.size>100*1024*1024)){setManualError('单个附件不能超过 100 MiB');return}if(files.reduce((sum,file)=>sum+file.size,0)>200*1024*1024){setManualError('附件总量不能超过 200 MiB');return}const submit=$('manual-submit');submit.disabled=true;const original=submit.textContent;submit.textContent=files.length?'上传中…':'提交中…';try{const upload=files.length?await uploadManualFiles(files):null;submit.textContent='提交中…';const result=await api('/v1/manual/jobs',{method:'POST',body:JSON.stringify({tasks,concurrency:Number($('manual-concurrency').value),raceAgents:Number($('manual-race-agents').value),writeup:$('manual-writeup').checked,...(upload?{uploadId:upload.id}:{})})});state.manualJobId=result.job.id;$('manual-tasks').value='';$('manual-files').value='';renderManualFiles();await loadManualJobs()}catch(error){setManualError(error.message)}finally{submit.disabled=false;submit.textContent=original}};
  $('manual-stop').onclick=async()=>{if(!state.manualJobId)return;try{await api('/v1/manual/jobs/'+state.manualJobId+'/stop',{method:'POST',body:'{}'});await loadManualJobs()}catch(error){setManualError(error.message)}};
  $('question-bank-start').onclick=async()=>{setManualError('');const button=$('question-bank-start');button.disabled=true;try{const result=await api('/v1/question-bank/jobs',{method:'POST',body:JSON.stringify({writeup:$('manual-writeup').checked})});state.manualJobId=result.job.id;await Promise.all([loadManualJobs(),loadQuestionBank()])}catch(error){setManualError(error.message);renderQuestionBank()}};
  function renderRuns(){const box=$('run-list');box.textContent='';for(const run of state.runs){const button=document.createElement('button');button.className='run'+(state.trace?.state?.id===run.id?' active':'');button.innerHTML='<div class="run-title"></div><div class="run-meta"><span class="dot"></span><span></span></div>';button.querySelector('.run-title').textContent=run.task;button.querySelector('.dot').classList.add(run.status);button.querySelector('.run-meta span:last-child').textContent=(run.category||run.status)+' · '+fmtTime(run.createdAt);button.onclick=()=>loadTrace(run.id);box.appendChild(button)}}
  async function loadRuns(){state.runs=(await api('/v1/runs')).runs;renderRuns();if(state.tab==='runs'&&!state.trace&&state.runs[0])await loadTrace(state.runs[0].id)}
  const icons={turn:'轮',decision:'判',plan:'计',action:'行',observation:'证',checkpoint:'检',hypothesis:'假',revision:'改',finding:'发',lesson:'验',outcome:'终'};
  function renderTrace(){const t=state.trace,s=t.state;$('trace-empty').hidden=true;$('trace').hidden=false;$('trace-title').textContent=s.task.task.split('\\n')[0];$('trace-category').textContent=s.task.metadata.category||s.status;$('trace-id').textContent=s.id+' · sandbox '+s.sandboxNamespace;$('integrity').textContent=t.integrity.valid?'审计链完整':'审计链异常';$('stats').innerHTML='<span><strong>'+s.turns+'</strong>回合</span><span><strong>'+s.toolCalls+'</strong>工具调用</span><span><strong>'+(s.hypotheses?.length||0)+'</strong>假设</span><span><strong>'+(s.strategyRevisions?.length||0)+'</strong>策略修订</span><span><strong>'+s.findings.length+'</strong>发现</span><span><strong>'+(s.lessons?.length||0)+'</strong>候选经验</span>';const box=$('timeline');box.textContent='';for(const ev of t.timeline){const button=document.createElement('button');button.className='event kind-'+ev.kind+(ev.status==='denied'?' denied':'');button.innerHTML='<span class="node"></span><span class="event-card"><span class="event-head"><span class="event-title"></span><span class="event-time"></span></span><span class="event-summary"></span></span>';button.querySelector('.node').textContent=icons[ev.kind]||'·';button.querySelector('.event-title').textContent=ev.title;button.querySelector('.event-time').textContent='#'+ev.sequence+' · '+fmtTime(ev.timestamp);button.querySelector('.event-summary').textContent=ev.summary;button.onclick=()=>selectEvent(ev,button);box.appendChild(button)}renderRuns();renderReviewLog()}
  async function loadTrace(id){state.trace=await api('/v1/runs/'+id+'/trace');state.selected=null;renderTrace();$('detail-title').textContent='尚未选择步骤';$('detail').textContent='选择时间线记录';$('review-form').hidden=true}
  function selectEvent(ev,button){document.querySelectorAll('.event.active').forEach(item=>item.classList.remove('active'));button.classList.add('active');state.selected=ev;$('detail-title').textContent=ev.title+' · #'+ev.sequence;$('detail').textContent=JSON.stringify(ev.data,null,2);$('review-form').hidden=false;renderReviewLog()}
  function renderReviewLog(){const box=$('review-log');box.textContent='';if(!state.trace)return;const reviews=state.trace.reviews.filter(review=>!state.selected||review.sequence===state.selected.sequence);for(const review of reviews){const div=document.createElement('div');div.className='review-item';div.textContent=review.verdict+' · '+review.note+(review.correction?'\\n修正：'+review.correction:'');box.appendChild(div)}}
  $('review-form').onsubmit=async event=>{event.preventDefault();if(!state.selected)return;const body={sequence:state.selected.sequence,verdict:$('review-verdict').value,note:$('review-note').value,correction:$('review-correction').value};const review=await api('/v1/runs/'+state.trace.state.id+'/reviews',{method:'POST',body:JSON.stringify(body)});state.trace.reviews.push(review);$('review-note').value='';$('review-correction').value='';renderReviewLog()};
  async function loadExperiences(){const records=(await api('/v1/experiences')).experiences;const box=$('experience-list');box.textContent='';if(!records.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='暂无平台验真经验';box.appendChild(empty);return}for(const record of records){const card=document.createElement('article');card.className='lesson';const h=document.createElement('h3');h.textContent=record.title;const meta=document.createElement('div');meta.className='muted';meta.textContent=record.category+' · '+fmtTime(record.promotedAt);const list=document.createElement('ul');for(const step of record.strategy){const li=document.createElement('li');li.textContent=step;list.appendChild(li)}const actions=document.createElement('div');actions.className='lesson-actions';const badge=document.createElement('span');badge.className='badge '+(record.status==='disabled'?'disabled':'');badge.textContent=record.status==='active'?'已启用':'已停用';const button=document.createElement('button');button.className='ghost';button.textContent=record.status==='active'?'停用':'启用';button.onclick=async()=>{const note=prompt('复核备注','')??'';await api('/v1/experiences/'+record.id,{method:'PATCH',body:JSON.stringify({status:record.status==='active'?'disabled':'active',reviewNote:note})});await loadExperiences()};actions.append(badge,button);card.append(h,meta,list,actions);box.appendChild(card)}}
  function show(tab){state.tab=tab;for(const name of ['arena','manual','runs','experience']){$(name+'-screen').hidden=name!==tab;$(name+'-tab').setAttribute('aria-selected',String(name===tab))}if(tab==='runs')loadRuns().catch(console.error);if(tab==='experience')loadExperiences().catch(console.error);if(tab==='arena')loadArenaStatus().catch(error=>setArenaError(error.message));if(tab==='manual')Promise.all([loadManualJobs(),loadQuestionBank()]).catch(error=>setManualError(error.message))}
  $('arena-tab').onclick=()=>show('arena');$('manual-tab').onclick=()=>show('manual');$('runs-tab').onclick=()=>show('runs');$('experience-tab').onclick=()=>show('experience');$('token-form').onsubmit=event=>{event.preventDefault();state.token=$('token-input').value;sessionStorage.setItem('xuanshu-token',state.token);$('token-modal').classList.remove('open');loadInitial()};
  async function loadInitial(){try{await Promise.all([loadArenaStatus(),loadManualJobs(),loadQuestionBank(),loadRuns()])}catch(error){if(error.message!=='unauthorized')setArenaError(error.message)}}
  loadInitial();setInterval(()=>{if(state.tab==='arena'&&state.jobId&&!terminal.has(state.job?.status))pollJob();else if(state.tab==='arena')loadArenaStatus().catch(()=>{});if(state.tab==='manual')Promise.all([loadManualJobs(),loadQuestionBank()]).catch(()=>{})},2000);setInterval(()=>loadRuns().catch(()=>{}),10000);
})();
</script>
</body>
</html>`;
}
